    for (let i = 0; i < lines.length; i++) {
      const lineNo = i + 1
      const line = lines[i].trim()
      if (line === '' || line.startsWith('#')) continue
      const t = line.split(/\s+/)
      try {
        const d = t[0]
        if (d === 'bucket' || d === 'window' || d === 'route') {
          if (started) throw new Fail('declarations must come before the first event')
        }
        if (d === 'bucket') {
          if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
          if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
          const capacity = num(t[2], 'capacity', 1)
          const refill = num(t[3], 'refill', 0)
          const per = num(t[4], 'per', 1)
          if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
          policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per })
        } else if (d === 'window') {
          if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
          if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
          const limit = num(t[2], 'limit', 0)
          const span = num(t[3], 'span', 1)
          if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
          policies.set(t[1], { name: t[1], kind: 'window', limit, span })
        } else if (d === 'route') {
          if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
          if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
          if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
          const list = []
          for (const n of t.slice(2)) {
            if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
            list.push(policies.get(n))
          }
          routes.set(t[1], list)
        } else if (d === 'event') {
          if (t.length !== 3) throw new Fail('expected event <tick> <key>')
          const tick = num(t[1], 'tick', 0)
          if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
          if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
          lastTick = tick
          started = true
          events.push({ tick, key: t[2] })
        } else {
          throw new Fail(`unknown directive ${d}`)
        }
      } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${lineNo}: ${e.message}`)
        throw e
      }
    }
  } catch (e) {
    if (e instanceof Fail) return die(`error: ${e.message}`)
    throw e
  }

  const prefixes = [...routes.keys()]
  const states = new Map()
  const stats = new Map()
  let ta = 0, td = 0
  const out = []

  const stateFor = (p, key, tick) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
      states.set(id, s)
    }
    return s
  }

  for (const ev of events) {
    let best = null
    for (const p of prefixes) if (ev.key.startsWith(p) && (best === null || p.length > best.length)) best = p
    let denier = null
    if (best !== null) {
