        const s = stateFor(p, ev.key, ev.tick)
        if (p.kind === 'bucket') {
          const n = ev.tick - s.last
          s.last = ev.tick
          s.num += p.refill * n
          const cap = p.capacity * p.per
          if (s.num > cap) s.num = cap
        } else {
          const cut = ev.tick - p.span
          s.ticks = s.ticks.filter((x) => x > cut)
        }
        return s
      })
      for (let i = 0; i < list.length; i++) {
        const p = list[i], s = ss[i]
        const ok = p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) { denier = p.name; break }
      }
