        list.forEach((p, i) => {
          if (p.kind === 'bucket') ss[i].num -= p.per
          else ss[i].ticks.push(ev.tick)
        })
      }
    }
    let st = stats.get(ev.key)
    if (!st) stats.set(ev.key, (st = { a: 0, d: 0 }))
    if (denier === null) { st.a++; ta++ } else { st.d++; td++ }
    out.push(denier === null ? `${ev.tick} ${ev.key} allow` : `${ev.tick} ${ev.key} deny ${denier}`)
  }

