    out.length = 0
    const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    for (const k of keys) out.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
    out.push(`total allowed=${ta} denied=${td}`)
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  return 0
}

