          s.ticks = s.ticks.filter((x) => x > cut)
        }
        return s
      })
      for (let i = 0; i < list.length; i++) {
        const p = list[i], s = ss[i]
        const ok = p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) { denier = p.name; break }
      }
      if (denier === null) {
        list.forEach((p, i) => {
          if (p.kind === 'bucket') ss[i].num -= p.per
          else ss[i].ticks.push(ev.tick)
        })
      }
    }
    let st = stats.get(ev.key)
    if (!st) stats.set(ev.key, (st = { a: 0, d: 0 }))
    if (denier === null) { st.a++; ta++ } else { st.d++; td++ }
    out.push(denier === null ? `${ev.tick} ${ev.key} allow` : `${ev.tick} ${ev.key} deny ${denier}`)
  }

  if (mode === 'summary') {
    out.length = 0
    const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    for (const k of keys) out.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
    out.push(`total allowed=${ta} denied=${td}`)
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  return 0
}

function die(msg) {
  process.stderr.write(msg + '\n')
  process.exitCode = 2
  return 2
}

